435	function snippetAround(content: string, query: string): string {
436	  const at = content.toLowerCase().indexOf(query.toLowerCase());
437	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
438	
439	  const start = Math.max(0, at - SNIPPET_RADIUS);
440	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
441	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
442	    end < content.length ? "…" : ""
443	  }`;
444	}
