636	 */
637	export async function upsertSearchDocument(
638	  orgId: OrgId,
639	  subjectKind: SearchSubjectKind,
640	  subjectId: string,
641	  content: string,
642	  projectId: ProjectId | null,
643	): Promise<void> {
644	  const db = getDb();
645	  const indexedAt = toIsoTimestamp(new Date());
646	
647	  const existing = db
648	    .select({ id: searchIndex.id })
649	    .from(searchIndex)
650	    .where(
651	      and(
652	        orgPredicate(searchIndex.orgId, orgId),
653	        eq(searchIndex.subjectKind, subjectKind),
654	        eq(searchIndex.subjectId, subjectId),
655	      ),
656	    )
