894	/**
895	 * In-process, typed publish/subscribe bus.
896	 *
897	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
898	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
899	 * every reactive concern `subscribe()`s at module init (see
900	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
901	 * throwing handler never fails the emit or the sibling handlers.
902	 */
903	
904	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
905	
906	const handlers = new Map<TaskflowEventType, HandlerSet>();
907	
908	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
909	
910	/** Registers a handler for one event type. Call the return value to detach. */
911	export function subscribe<K extends TaskflowEventType>(
912	  type: K,
913	  handler: EventHandler<K>,
914	): Unsubscribe {
915	  const set = handlers.get(type) ?? new Set();
916	  set.add(handler as EventHandler<TaskflowEventType>);
917	  handlers.set(type, set);
918	  return () => {
919	    set.delete(handler as EventHandler<TaskflowEventType>);
920	  };
921	}
922	
923	/** Registers a handler that detaches itself after the first delivery. */
924	export function subscribeOnce<K extends TaskflowEventType>(
925	  type: K,
926	  handler: EventHandler<K>,
927	): Unsubscribe {
928	  const off = subscribe(type, (payload) => {
929	    off();
930	    return handler(payload);
931	  });
932	  return off;
933	}
