935	/**
936	 * Publishes an event to every subscriber. Resolves once all handlers settle;
937	 * rejected handlers are reported to the error sinks, never rethrown.
938	 */
939	export async function emit<K extends TaskflowEventType>(
940	  type: K,
941	  payload: TaskflowEventPayload<K>,
942	): Promise<void> {
943	  const set = handlers.get(type);
944	  if (!set || set.size === 0) return;
945	
946	  const results = await Promise.allSettled(
947	    [...set].map(async (handler) => {
948	      await (handler as EventHandler<K>)(payload);
949	    }),
950	  );
951	
952	  for (const result of results) {
953	    if (result.status === "rejected") {
954	      reportHandlerError(type, result.reason);
955	    }
956	  }
957	}
