959	/** Fire-and-forget variant for call sites that must not await delivery. */
960	export function emitAndForget<K extends TaskflowEventType>(
961	  type: K,
962	  payload: TaskflowEventPayload<K>,
963	): void {
964	  void emit(type, payload).catch((error: unknown) => {
965	    reportHandlerError(type, error);
966	  });
967	}
