969	export function onHandlerError(
970	  sink: (type: TaskflowEventType, error: unknown) => void,
971	): Unsubscribe {
972	  errorSinks.add(sink);
973	  return () => {
974	    errorSinks.delete(sink);
975	  };
976	}
