978	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
979	  for (const sink of errorSinks) {
980	    try {
981	      sink(type, error);
982	    } catch {
983	      // A failing error sink must never escalate.
984	    }
985	  }
986	}
