type NumberingDb = Pick<ReturnType<typeof getDb>, "select" | "insert">;

/**
 * Highest number the project has ever issued: the remembered high-water mark
 * or the highest number on a row still in the project, whichever is larger
 * (rows written before the counter existed, or by a seed, only show up in the
 * latter).
 */
function highestIssuedNumber(
  db: NumberingDb,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const counter = db
    .select({ value: projectIssueCounters.lastNumber })
    .from(projectIssueCounters)
    .where(
      and(
        orgPredicate(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .get();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(counter?.value ?? 0, row?.value ?? 0);
}

/** Raises the project's high-water mark to at least `issueNumber`. */
function rememberIssuedNumber(
  db: NumberingDb,
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  db.insert(projectIssueCounters)
    .values({ projectId, orgId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: projectIssueCounters.projectId,
      set: {
        lastNumber: sql`max(${projectIssueCounters.lastNumber}, ${issueNumber})`,
      },
    })
    .run();
}

/**
 * Next per-project issue number. A number that has ever been used in a
 * project is never issued again there — archived issues keep theirs, and the
 * number of an issue that moved away stays retired — so this continues after
 * the highest number the project has ever issued, not the highest present.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssuedNumber(getDb(), orgId, projectId) + 1;
}

