 * Moves an issue into another project of the same org (ADR 0011). The issue
 * takes the target project's next number, allocated exactly as a new issue's
 * would be, and its old number is retired in the source project. Only the
 * project, the number and `updated_at` change; one transaction, so a failure
 * leaves both projects as they were.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const fromProjectId = current.projectId as ProjectId;
    if (fromProjectId === toProjectId) return;

    // Retire every number the source has issued so far, this one included.
    rememberIssuedNumber(
      tx,
      orgId,
      fromProjectId,
      highestIssuedNumber(tx, orgId, fromProjectId),
    );

    const toNumber = highestIssuedNumber(tx, orgId, toProjectId) + 1;
    tx.update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();
    rememberIssuedNumber(tx, orgId, toProjectId, toNumber);
  });

  const moved = await findIssueById(orgId, issueId);
  if (!moved) throw new Error(`Issue ${issueId} not found`);
  return moved;
