sub(p,'''export async function getIssue(''','''/**
 * Moves an issue to another project of the same workspace (ADR 0011).
 *
 * Gates, in order: tenant scope, the `issue:update` every issue edit needs, a
 * live issue, a live target project in this org, the `issue:create` creating
 * there needs, and the target's per-project issue quota. Any refusal changes
 * nothing. The issue then takes the target's next number (its old one is
 * retired) and exactly one event, `issue.moved`, is published — the audit
 * entry and the search index hang off it. A move within the same project is a
 * no-op that publishes nothing.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const target = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", target.id, target);
  assertCan(actor, "issue:create", projectResource(target));

  if (before.projectId === target.id) return before;

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, target.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${target.key}`,
    );
  }

  const after = await issueRepo.moveIssueToProject(
    input.orgId,
    before.id,
    target.id,
  );

  // The index denormalises the project; keep it right even when no listener
  // is attached. The `issue.moved` subscriber re-reads and re-indexes as well.
  await searchRepo.relocateSearchDocument(
    input.orgId,
    "issue",
    after.id,
    after.projectId,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId: before.projectId,
    toProjectId: after.projectId,
    fromNumber: before.number,
    toNumber: after.number,
  });

  return after;
}

